require_once __DIR__ . '/../config/config.php';require_once __DIR__ . '/../includes/functions.php';require_login();if(is_admin())redirect('admin/dashboard.php');if($_SERVER['REQUEST_METHOD']!=='POST'){redirect('index.php');}verify_csrf();$id=(int)($_POST['course_id']??0);$st=$pdo->prepare("SELECT id FROM courses WHERE id=? AND status='published' AND is_free=1");$st->execute([$id]);if(!$st->fetch()){flash('error','This free course is not available.');redirect('index.php');}$ins=$pdo->prepare("INSERT INTO enrollments(user_id,course_id,status) VALUES(?,?,'approved') ON DUPLICATE KEY UPDATE status='approved',reviewed_at=NOW()");$ins->execute([current_user()['id'],$id]);flash('success','You are now enrolled in this free course.');redirect('student/dashboard.php');
